#!/usr/bin/env python3
"""Consolidated Microsoft TEST scheduling deployment. No external dependencies.

--check: collect local blockers and repairs without changing files or calling APIs.
Default: full inventory, safe permission repair, fresh Microsoft READ, backup,
resumable installation, then TEST activation as the final write. Never sends mail,
creates appointments, changes payment gates, or updates booking rows.
"""
import base64
import fcntl
import hashlib
import json
import os
from pathlib import Path
import pwd
import re
import sqlite3
import stat
import subprocess
import sys
import tempfile
import types
import zlib

REVISION = '20260927-r1'
RELEASE = 'sitesee-microsoft-scheduling-test-v1'
BUNDLE = ''
BUNDLE_SHA = 'b9dbe9f6a0e167115ed6ffd93b8edb32fcc0a134471fbb41a064441e49f44abb'
RECOVERY = ''
RECOVERY_SHA = '70ae3a52dd15e0264b0dba768503e73e8b7f077a2a60e678b9a715c345fe84eb'
JOURNAL = 'microsoft-scheduling-install.json'
ACTIVATION = 'microsoft-scheduling.json'
NAMES = ('server/booking-scheduling-provider.php', 'server/booking-confirmation.php',
         'server/booking-invitation.php', 'server/booking-availability-check.php', 'server/booking-staff.php',
         'tools/diagnose-calendar-confirmation.php','tools/audit-calendar-confirmation.php')


def modules():
    raw = zlib.decompress(base64.b64decode(RECOVERY))
    if hashlib.sha256(raw).hexdigest() != RECOVERY_SHA:
        raise RuntimeError('Recovery module integrity differs.')
    r = types.ModuleType('reviewed_ms_recovery')
    r.__file__ = __file__
    exec(compile(raw, 'reviewed-recovery', 'exec'), r.__dict__)
    return r, r.embedded_installer()


def bundle(m):
    raw = zlib.decompress(base64.b64decode(BUNDLE))
    m.need(hashlib.sha256(raw).hexdigest() == BUNDLE_SHA, 'Scheduling payload integrity differs.')
    data = json.loads(raw)
    m.need(set(data['files']) == set(NAMES), 'Scheduling package paths differ.')
    return {k: v.encode() for k, v in data['files'].items()}, data['before']


def activation(m):
    return m.encode({'schema': 1, 'stage': 'test', 'provider': 'microsoft', 'enabled': True,
        'confirmation_stage': 'test', 'confirmation_enabled': True, 'invitations_enabled': True,
        'test_recipient_email': 'cro@sitesee.ai', 'calendar_uid': 'microsoft:' + m.CONFIG['calendar_id']})


def desired(m, root, files):
    values = {name: files[name] for name in NAMES}
    manifest = json.loads(m.private_bytes(root / 'calendar-confirmation-release.json', root.stat().st_uid, private=False))
    manifest['files'].update({name: m.digest(data) for name, data in files.items()})
    manifest['files']['server/booking-microsoft-calendar.php'] = m.digest(m.payload()['server/booking-microsoft-calendar.php'])
    values['calendar-confirmation-release.json'] = m.encode(manifest)
    values['microsoft-scheduling-release.json'] = m.encode({'release': RELEASE, 'revision': REVISION,
        'files': {name: m.digest(data) for name, data in files.items()}})
    # The switch is always last: every dependency and controller exists beforehand.
    values[ACTIVATION] = activation(m)
    return values


def database_check(m, root):
    path = root / 'data/bookings.sqlite'
    s = path.lstat()
    m.need(stat.S_ISREG(s.st_mode) and not path.is_symlink() and s.st_nlink == 1
        and s.st_uid == root.stat().st_uid and not s.st_mode & 0o077, 'Booking database path/permissions differ; no automatic database repair is allowed.')
    db = sqlite3.connect('file:' + str(path) + '?mode=ro', uri=True, timeout=5)
    try:
        db.execute('PRAGMA query_only=ON')
        columns = {row[1] for row in db.execute('PRAGMA table_info(booking_confirmations)')}
        m.need({'reference','state','calendar_uid','event_uid','event_json','planned_start','planned_end','invitation_state'} <= columns,
               'Booking confirmation schema differs.')
        rows = list(db.execute('SELECT state,calendar_uid,planned_start,planned_end FROM booking_confirmations'))
        for state, calendar, start, end in rows:
            m.need(state in ('creating','uncertain','confirmed') and isinstance(start, int) and isinstance(end, int) and end > start
                and (re.fullmatch(r'[a-f0-9]{32}', calendar or '') or calendar == 'microsoft:' + m.CONFIG['calendar_id']),
                'Existing reservation identity or interval needs review; no reservation was changed.')
        return len(rows)
    finally:
        db.close()


def inventory(r, m, root, php, uid, files, before, account=None, credentials=None):
    report = r.inventory(m, root, m.payload(), php, uid, account=account, credentials=credentials)
    for name, content in files.items():
        current = report.file(root / name, optional=name not in before)
        if current is None:
            continue
        if m.digest(current) not in {m.digest(content), before.get(name)}:
            report.issue('Scheduling source differs from the reviewed old/new versions: ' + name)
        report.readable.add(root / name)
    for name in ('microsoft-scheduling-release.json', ACTIVATION):
        if (root / name).exists() or (root / name).is_symlink():
            actual = report.file(root / name, private=True)
            if name == ACTIVATION and actual is not None and actual != activation(m):
                report.issue('Existing scheduling activation differs; preserved.')
            if name.startswith('microsoft-scheduling-release') and actual is not None:
                expect = m.encode({'release': RELEASE, 'revision': REVISION, 'files': {k:m.digest(v) for k,v in files.items()}})
                if actual != expect: report.issue('Existing scheduling release differs; preserved.')
    j = report.json(root / 'microsoft-calendar-probe.json', private=True)
    if not r.valid_journal(j, m.CONFIG) or j.get('state') != 'complete':
        report.issue('A completed Microsoft create/read/remove test is required; the probe journal was preserved.')
    report.guarded('Stored reservations (read only)', lambda: database_check(m, root))
    # Scheduling still supports existing Zoho claims. Check their private files together.
    for name in ('zoho-calendar.json', 'zoho-confirmation.json'):
        c = report.json(root / name, private=True)
        if c is not None and (not re.fullmatch(r'[a-f0-9]{32}', str(c.get('calendar_uid',''))) or not c.get('enabled')):
            report.issue('Existing Zoho identity/readiness differs: ' + name)
        report.readable.add(root / name)
    with tempfile.TemporaryDirectory(prefix='sitesee-scheduling-lint-') as directory:
        for name, content in files.items():
            def lint(name=name, content=content):
                target = Path(directory) / Path(name).name
                target.write_bytes(content)
                p = subprocess.run([php, '-l', str(target)], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=30)
                m.need(p.returncode == 0, 'PHP syntax check failed: ' + name)
            report.guarded('Scheduling syntax', lint)
    report.guarded('Scheduling application-user access', lambda: m.runtime_check(php, root,
        sorted(report.folders), report.readable, uid, account))
    return report


def fresh_read(m, root, php, account):
    # Uses the previously verified, hash-pinned adapter. No event mutation is possible here.
    code = r'''
ini_set('display_errors','0');
try {
 $root=$argv[1]; require $root.'/server/booking-microsoft-calendar.php';
 $config=booking_ms_private_json($root.'/microsoft-calendar.json');
 $secret=booking_ms_private_json($config['graph_credentials']);
 $read=booking_ms_connection($config,$secret);
 booking_ms_verify_calendar($read);
 $snapshot=booking_ms_snapshot($read,['start'=>time(),'end'=>time()+15*86400]);
 echo "MICROSOFT_READ_PASS\n";
} catch (Throwable $e) {
 echo $e instanceof BookingMicrosoftCalendarError ? $e->getMessage() : 'Microsoft availability read could not complete.';
 exit(1);
}
'''
    p = subprocess.run([php, '-d', 'display_errors=0', '-r', code, str(root)],
        preexec_fn=m.account_switch(account), stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=180)
    result = p.stdout.decode('utf-8','replace')[:2048]
    m.need(p.returncode == 0 and result.strip() == 'MICROSOFT_READ_PASS', 'Fresh Microsoft read failed: ' + result)


def load_journal(m, root, uid):
    p = m.safe_path(root, JOURNAL)
    if not p.exists(): return None
    j = json.loads(m.private_bytes(p, uid))
    m.need(j.get('release') == RELEASE and j.get('revision') == REVISION and isinstance(j.get('entries'), dict)
        and j.get('state') in ('prepared','installed','restored'), 'Scheduling recovery record differs; preserve it.')
    return j


def recover(m, root, uid, gid, check=False):
    j = load_journal(m, root, uid)
    if j is None or j['state'] in ('installed','restored'): return
    allowed = set(NAMES) | {'calendar-confirmation-release.json','microsoft-scheduling-release.json',ACTIVATION}
    m.need(set(j['entries']) == allowed, 'Recovery paths differ; preserve the recovery record.')
    folder = root / 'deployment-backups' / j['backup']
    m.need(bool(re.fullmatch(r'microsoft-scheduling-[A-Za-z0-9_-]+', j['backup'])), 'Recovery directory differs.')
    m.safe_path(root, 'deployment-backups/' + j['backup'])
    config = m.safe_path(root, ACTIVATION)
    if config.exists():
        # Once the switch exists, an appointment might have been created. NEVER roll back.
        for name, entry in j['entries'].items():
            m.need(m.digest(m.private_bytes(root / name, uid, private=False)) == entry['new'], 'Activated deployment is incomplete; retain all files and the recovery record.')
        if not check:
            j['state'] = 'installed'; m.atomic_write(root / JOURNAL, m.encode(j), uid, gid)
        return
    m.need(not check, 'An interrupted, inactive deployment can be recovered by rerunning this command without --check.')
    restore = []
    for name, entry in j['entries'].items():
        path = m.safe_path(root,name)
        current = m.digest(m.private_bytes(path,uid,private=False)) if path.exists() else None
        m.need(current in (entry['old'],entry['new']), 'Recovery found an unrelated change: ' + name)
        old = None
        if entry['old'] is not None:
            old = m.private_bytes(folder / name, os.geteuid())
            m.need(m.digest(old) == entry['old'], 'Recovery backup integrity differs: ' + name)
        restore.append((path,old))
    for path, old in sorted(restore, key=lambda item: item[1] is None):
        if old is None:
            if path.exists(): path.unlink()
        else: m.atomic_write(path,old,uid,gid)
    j['state']='restored';m.atomic_write(root / JOURNAL,m.encode(j),uid,gid)
    print('Interrupted inactive deployment restored automatically; continuing full preflight.',flush=True)


def deploy(m, root, values, uid, gid, write=None):
    write = write or m.atomic_write
    if all((root / name).exists() and m.private_bytes(root / name,uid,private=False) == data for name,data in values.items()):
        return None
    m.need(not (root / ACTIVATION).exists(), 'An active scheduling release differs; do not roll it back or overwrite it.')
    base=m.safe_path(root,'deployment-backups')
    if not base.exists(): base.mkdir(mode=0o700)
    m.need(not base.is_symlink() and base.is_dir() and not base.stat().st_mode & 0o022,'Backup directory is unsafe.')
    folder=Path(tempfile.mkdtemp(prefix='microsoft-scheduling-',dir=str(base)))
    entries={}
    for name,data in values.items():
        path=m.safe_path(root,name);old=m.private_bytes(path,uid,private=False) if path.exists() else None
        if old is not None:
            backup=folder/name;backup.parent.mkdir(mode=0o700,parents=True,exist_ok=True)
            m.atomic_write(backup,old,os.geteuid(),os.getegid())
        entries[name]={'old':m.digest(old) if old is not None else None,'new':m.digest(data)}
    j={'release':RELEASE,'revision':REVISION,'state':'prepared','backup':folder.name,'entries':entries}
    m.atomic_write(root/JOURNAL,m.encode(j),uid,gid)
    try:
        for name,data in values.items():
            path=m.safe_path(root,name)
            current=m.digest(m.private_bytes(path,uid,private=False)) if path.exists() else None
            m.need(current==entries[name]['old'],'Deployment target changed concurrently: '+name)
            if name == ACTIVATION:
                for previous, expected in values.items():
                    if previous != ACTIVATION:
                        m.need(m.private_bytes(root/previous,uid,private=False)==expected,'Pre-activation verification differs: '+previous)
            write(path,data,uid,gid)
        for name,data in values.items():
            m.need(m.private_bytes(root/name,uid,private=False)==data,'Final installed bytes differ: '+name)
        j['state']='installed';m.atomic_write(root/JOURNAL,m.encode(j),uid,gid)
    except Exception:
        recover(m,root,uid,gid)
        raise
    return folder


def main():
    r,m=modules()
    m.need(sys.argv[1:] in ([],['--check']),'Run without arguments, or --check for local inspection.')
    m.need(os.geteuid()==0,'Run in WHM Terminal as root.')
    account=pwd.getpwnam('sitesee');uid,gid=account.pw_uid,account.pw_gid
    root,php=m.ROOT,m.PHP;os.umask(0o077);files,before=bundle(m)
    print('Microsoft TEST scheduling | Revision: '+REVISION,flush=True)
    print('Installer SHA256: '+hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),flush=True)
    lock=os.open(str(root),os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
    confirm=None
    try:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        check=sys.argv[1:]==['--check']
        m.need(not m.directory_check(root,uid,root=True),'Application root ownership or permissions differ; preserve it for review.')
        recover(m,root,uid,gid,check)
        report=inventory(r,m,root,php,uid,files,before,account)
        r.show_inventory(report,lambda message:print(message,flush=True))
        m.need(not report.errors,'All detected independent local blockers are listed above; no installation was started.')
        if check:
            print('FINAL RESULTS\nLocal scheduling inspection: PASS\nNo changes or provider calls.');return
        audit=r.apply_repairs(m,report,uid,gid)
        report=inventory(r,m,root,php,uid,files,before,account)
        m.need(not report.errors and not report.repairs,'Post-repair inventory changed; retain the repair record.')
        path=m.safe_path(root,'booking-confirmation.lock')
        if path.exists(): m.private_bytes(path,uid)
        confirm=os.open(str(path),os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW|os.O_NONBLOCK,0o600)
        info=os.fstat(confirm)
        m.need(stat.S_ISREG(info.st_mode) and info.st_nlink==1 and not info.st_mode & 0o077 and info.st_uid in (0,uid),'Confirmation lock type, owner or mode differs.')
        os.fchown(confirm,uid,gid)
        fcntl.flock(confirm,fcntl.LOCK_EX|fcntl.LOCK_NB)
        print('Fresh Microsoft calendar and availability read (no event write)...',flush=True)
        fresh_read(m,root,php,account)
        saved=deploy(m,root,desired(m,root,files),uid,gid)
        print('\nFINAL RESULTS\nMicrosoft scheduling: ENABLED IN TEST MODE')
        print('New confirmations: sales@re.sitesee.ai / Calendar')
        print('Existing Zoho appointment identities and reservations: preserved')
        print('Customer availability and staff alternatives: Microsoft plus stored reservations')
        print('Active release hashes: PASS')
        print('No booking row, payment, calendar event, invitation, email, credential or Zoho setting was changed.')
        print('Actual Microsoft booking confirmation and invitation flow: NOT YET VERIFIED')
        if saved: print('Backup: '+str(saved))
        else: print('Existing scheduling installation: unchanged')
        if audit: print('Permission recovery record: '+str(audit))
        print('Next: send this FINAL RESULTS block for review before the one-booking TEST.')
    finally:
        if confirm is not None: os.close(confirm)
        os.close(lock)


if __name__=='__main__':
    try: main()
    except Exception as error:
        # Do not print exception payloads from credentials, SQLite or provider JSON.
        try:
            _,m=modules()
            message=str(error) if error.__class__.__name__=='InstallError' else 'A local check could not complete ('+type(error).__name__+').'
        except Exception: message='Installer integrity or local runtime check failed.'
        print('\nFINAL RESULTS\nMicrosoft TEST scheduling: STOPPED\n'+message)
        if (Path('/home/sitesee/.sitesee-real-estate')/ACTIVATION).exists():
            print('Scheduling switch is present: activation may already have completed. Do not roll back; rerun this installer for verification.')
        print('Keep the installation journal and backups. Rerun this same installer after review; never restore an older controller over Microsoft appointments.')
        sys.exit(1)
